@CategoryID_a5c607129cb3 UNIQUEIDENTIFIER,
@UserQuestion_a5c607129cb3 NVARCHAR(MAX),
@Description_a5c607129cb3 NVARCHAR(MAX),
@SQL_a5c607129cb3 NVARCHAR(MAX),
@TechnicalDescription_a5c607129cb3 NVARCHAR(MAX),
@OriginalSQL_a5c607129cb3 NVARCHAR(MAX),
@Feedback_a5c607129cb3 NVARCHAR(MAX),
@Status_a5c607129cb3 NVARCHAR(15),
@QualityRank_a5c607129cb3 INT,
@ExecutionCostRank_a5c607129cb3 INT,
@UsesTemplate_a5c607129cb3 BIT,
@AuditQueryRuns_a5c607129cb3 BIT,
@CacheEnabled_a5c607129cb3 BIT,
@CacheTTLMinutes_a5c607129cb3 INT,
@CacheMaxSize_a5c607129cb3 INT,
@EmbeddingVector_a5c607129cb3 NVARCHAR(MAX),
@EmbeddingModelID_a5c607129cb3 UNIQUEIDENTIFIER,
@CacheValidationSQL_a5c607129cb3 NVARCHAR(MAX),
@SQLDialectID_a5c607129cb3 UNIQUEIDENTIFIER,
@Reusable_a5c607129cb3 BIT,
@ExternalDataSourceID_a5c607129cb3 UNIQUEIDENTIFIER,
@IsMaterialized_a5c607129cb3 BIT,
@ID_a5c607129cb3 UNIQUEIDENTIFIER
SET
  @Name_a5c607129cb3 = N'Common: Party Lookup Organizations'
SET
  @CategoryID_a5c607129cb3 = '6C0A1000-0000-4000-A000-000000000001'
SET
  @UserQuestion_a5c607129cb3 = N'Which organizations match what the user is typing into an organization picker?'
SET
  @Description_a5c607129cb3 = N'Up to 20 organizations whose name, legal name or acronym starts with the typed term, or whose website domain starts with the typed domain. Backs bizapps-party-field.'
SET
  @SQL_a5c607129cb3 = N'-- Party lookup for Organizations: prefix match on indexed base-table columns, TOP 20, no COUNT.
-- Contract shared by every party lookup query (bizapps-party-field): columns ID, Name, Detail;
-- parameters Term (required) and Domain (optional, already normalized by the picker).
-- sqlLikeBegins escapes the term and appends the trailing wildcard.
-- Detail shows the acronym and the website domain ("NAR · nar.realtor"), whichever exist, so two
-- organizations with the same name or acronym can be told apart.
SELECT TOP 20
    o.ID,
    o.Name,
    NULLIF(CONCAT_WS(N'' · '', o.Acronym, o.WebsiteDomain), N'''') AS Detail
FROM [__mj_BizAppsCommon].[Organization] o
WHERE o.Name LIKE {{ Term | sqlLikeBegins }}
   OR o.LegalName LIKE {{ Term | sqlLikeBegins }}
   OR o.Acronym LIKE {{ Term | sqlLikeBegins }}
{% if Domain %}   OR o.WebsiteDomain LIKE {{ Domain | sqlLikeBegins }}
{% endif %}ORDER BY o.Name, o.ID
'
SET
  @TechnicalDescription_a5c607129cb3 = N'Grain: one row per Organization, TOP 20 ordered by Name, ID. Base table __mj_BizAppsCommon.Organization, prefix LIKE on indexed Name, LegalName, Acronym and WebsiteDomain; no view, no COUNT. Parameters: Term (required), Domain (optional, lower-cased host without scheme, www. or path). Columns: ID, Name, Detail (Acronym and WebsiteDomain joined by '' · '', whichever are set).'
SET
  @Status_a5c607129cb3 = N'Approved'
SET
  @QualityRank_a5c607129cb3 = 9
SET
  @ExecutionCostRank_a5c607129cb3 = 1
SET
  @UsesTemplate_a5c607129cb3 = 1
SET
  @AuditQueryRuns_a5c607129cb3 = 0
SET
